SELECT nickname, role, deleted_at
FROM users
WHERE uuid IN (
    UUID_TO_BIN('00000000-0000-0000-0000-000000000001'),
    UUID_TO_BIN('00000000-0000-0000-0000-000000000002'),
    UUID_TO_BIN('00000000-0000-0000-0000-000000000003')
)
ORDER BY nickname;

SELECT s.stage_id, s.name, s.difficulty, COUNT(sr.round_id) AS round_count
FROM stages s
LEFT JOIN stage_rounds sr ON sr.stage_id = s.stage_id
WHERE s.stage_id IN (1, 2)
GROUP BY s.stage_id, s.name, s.difficulty
ORDER BY s.stage_id;

SELECT s.name AS stage_name,
       u.nickname,
       COUNT(rec.stage_record_id) AS attempts,
       MIN(CASE WHEN rec.is_clear = 1 THEN rec.stage_play_time_ms END) AS best_clear_time_ms
FROM stage_records rec
JOIN users u ON u.uuid = rec.uuid
JOIN stages s ON s.stage_id = rec.stage_id
WHERE rec.stage_record_id IN (1001, 1002, 1003, 1004, 2001, 2002, 2003)
GROUP BY s.stage_id, s.name, u.uuid, u.nickname
ORDER BY s.stage_id, best_clear_time_ms, u.nickname;
